import jwt
from jwt import PyJWT
from cryptography.hazmat.primitives.asymmetric import rsa
from cryptography.hazmat.primitives import serialization
from datetime import datetime, timedelta, timezone
import time

# --- Key Generation (Run once, store keys securely) ---
def generate_keys():
    private_key = rsa.generate_private_key(public_exponent=65537, key_size=2048)
    public_key = private_key.public_key()

    pem_private = private_key.private_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PrivateFormat.PKCS8,
        encryption_algorithm=serialization.NoEncryption()
    )
    pem_public = public_key.public_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PublicFormat.SubjectPublicKeyInfo
    )
    return pem_private, pem_public

# --- Configuration ---
PRIVATE_KEY_PEM, PUBLIC_KEY_PEM = generate_keys()
ALGORITHM = "RS256"
ISSUER = "auth-service"
AUDIENCE = "api-gateway"
TOKEN_TTL_MINUTES = 15

# --- Token Generation ---
def create_token(user_id: str, roles: list[str], extra_claims: dict = None) -> str:
    now = datetime.now(timezone.utc)
    payload = {
        "sub": user_id,
        "iat": now,
        "exp": now + timedelta(minutes=TOKEN_TTL_MINUTES),
        "iss": ISSUER,
        "aud": AUDIENCE,
        "roles": roles,
        "jti": jwt.utils.uuid4().hex  # Unique token ID for revocation lists
    }
    if extra_claims:
        payload.update(extra_claims)

    return PyJWT().encode(payload, PRIVATE_KEY_PEM, algorithm=ALGORITHM)

# --- Token Validation ---
def validate_token(token: str, leeway_seconds: int = 10) -> dict:
    try:
        # options={'verify_aud': True} ensures audience check happens
        decoded = PyJWT().decode(
            token,
            PUBLIC_KEY_PEM,
            algorithms=[ALGORITHM],
            audience=AUDIENCE,
            issuer=ISSUER,
            leeway=leeway_seconds,
            options={"require": ["exp", "iat", "iss", "aud", "sub", "jti"]}
        )
        return {"valid": True, "payload": decoded}
    except jwt.ExpiredSignatureError:
        return {"valid": False, "error": "Token expired"}
    except jwt.InvalidAudienceError:
        return {"valid": False, "error": "Invalid audience"}
    except jwt.InvalidIssuerError:
        return {"valid": False, "error": "Invalid issuer"}
    except jwt.InvalidTokenError as e:
        return {"valid": False, "error": f"Invalid token: {str(e)}"}

# --- Usage Example ---
if __name__ == "__main__":
    # 1. Generate
    token = create_token(user_id="user_123", roles=["admin", "user"], extra_claims={"scope": "read:write"})
    print(f"Generated Token:\n{token}\n")

    # 2. Validate (Success)
    result = validate_token(token)
    print(f"Validation Result: {result}\n

