// server.js
require('dotenv').config();
const express = require('express');
const mongoose = require('mongoose');
const cors = require('cors');

// --- Configuração Inicial ---
const app = express();
const PORT = process.env.PORT || 3000;
const MONGO_URI = process.env.MONGO_URI || 'mongodb://localhost:27017/userapi';

// --- Middlewares Globais ---
app.use(cors());
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// --- Conexão com MongoDB ---
mongoose.connect(MONGO_URI)
  .then(() => console.log('✅ Conectado ao MongoDB com sucesso'))
  .catch(err => console.error('❌ Erro ao conectar ao MongoDB:', err));

// --- Modelo (Schema) de Usuário ---
const userSchema = new mongoose.Schema({
  name: {
    type: String,
    required: [true, 'O nome é obrigatório'],
    trim: true,
    minlength: [2, 'O nome deve ter no mínimo 2 caracteres']
  },
  email: {
    type: String,
    required: [true, 'O email é obrigatório'],
    unique: true,
    lowercase: true,
    trim: true,
    match: [/^\S+@\S+\.\S+$/, 'Por favor, insira um email válido']
  },
  password: {
    type: String,
    required: [true, 'A senha é obrigatória'],
    minlength: [6, 'A senha deve ter no mínimo 6 caracteres'],
    select: false // Não retorna a senha por padrão nas queries
  },
  role: {
    type: String,
    enum: ['user', 'admin'],
    default: 'user'
  },
  isActive: {
    type: Boolean,
    default: true
  }
}, {
  timestamps: true // Cria createdAt e updatedAt automaticamente
});

// Middleware de hash de senha antes de salvar (simplificado para exemplo, use bcrypt em produção)
// Nota: Em produção, use: const bcrypt = require('bcrypt'); e faça o hash no pre('save')
userSchema.pre('save', async function(next) {
  if (!this.isModified('password')) return next();
  // Simulação de hash - SUBSTITUA POR BCRYPT EM PRODUÇÃO
  this.password = `hashed_${this.password}`; 
  next();
});

const User = mongoose.model('User', userSchema);

// --- Rotas da API (RESTful) ---

// Health Check
app.get('/health', (req, res) => {
  res.status(200).json({ status: 'OK', timestamp: new Date().toISOString() });
});

// CREATE - Criar novo usuário
// POST /api/users
app.post('/api/users', async (req, res) => {
  try {
    const { name, email, password, role } = req.body;

    // Verifica se email já existe
    const existingUser = await User.findOne({ email });
    if (existingUser) {
      return res.status(409).json({ error: 'Conflito', message: 'Email já cadastrado' });
    }

    const user = new User({ name, email, password, role });
    await

