    select: false // Não retorna a senha por padrão nas queries
  },
  role: {
    type: String,
    enum: ['user', 'admin'],
    default: 'user'
  },
  isActive: {
    type: Boolean,
    default: true
  }
}, {
  timestamps: true // Cria createdAt e updatedAt automaticamente
});

