// package.json dependencies implied:
// express, mongoose, zod, http-errors, helmet, cors, morgan, dotenv, express-rate-limit

import 'dotenv/config';
import express from 'express';
import mongoose from 'mongoose';
import { z } from 'zod';
import createError from 'http-errors';
import helmet from 'helmet';
import cors from 'cors';
import morgan from 'morgan';
import rateLimit from 'express-rate-limit';

// ==========================================
// 1. DATABASE & MODEL (Optimized Schema)
// ==========================================
const userSchema = new mongoose.Schema(
  {
    email: { type: String, required: true, unique: true, lowercase: true, index: true },
    passwordHash: { type: String, required: true, select: false }, // Never return hash by default
    name: { type: String, required: true, trim: true, maxlength: 100 },
    role: { type: String, enum: ['user', 'admin'], default: 'user' },
    isActive: { type: Boolean, default: true, index: true },
    lastLoginAt: { type: Date },
  },
  {
    timestamps: true, // createdAt, updatedAt
    versionKey: false, // Remove __v
    toJSON: { virtuals: true, transform: (_, ret) => { delete ret.passwordHash; return ret; } },
    toObject: { virtuals: true },
  }
);

// Virtual for public profile (innovation: computed property)
userSchema.virtual('profile').get(function () {
  return { id: this._id, name: this.name, email: this.email, role: this.role };
});

// Static helper for lean queries (performance)
userSchema.statics.findPublic = function (filter = {}) {
  return this.find(filter).select('name email role isActive createdAt').lean();
};

export const User = mongoose.model('User', userSchema);

// ==========================================
// 2. VALIDATION SCHEMAS (Zod - Type-safe)
// ==========================================
const createUserSchema = z.object({
  body: z.object({
    email: z.string().email(),
    password: z.string().min(8).max(128), // Hashing handled in service/controller
    name: z.string().min(1).max(100),
    role: z.enum(['user', 'admin']).optional(),
  }),
});

const updateUserSchema = z.object({
  params: z.object({ id: z.string().regex(/^[0-9a-fA-F]{24}$/, 'Invalid ID format') }),
  body: z.object({
    name: z.string().min(1).max(100).optional(),
    role: z.enum(['user', 'admin']).optional(),
    isActive: z.boolean().optional(),
  }).strict(),
});

const paramsIdSchema = z.object({
  params: z.object({ id: z.string().regex(/^[0-9a-fA-F]{24}$/, 'Invalid ID format') }),
});

// ==========================================
// 3. MIDDLEWARE FACTORY (Validation)
// ==========================================
const validate = (schema) => async (req, res, next) => {
  try {
    await schema.parseAsync

