// dicom-gateway.js
// Requer: Node.js 18+, CUDA Toolkit 12+, FFmpeg 6+ com suporte NVENC/NVDEC
// Instalar: npm install express dicom-parser sharp fluent-ffmpeg pako dicomweb-client multer js-yaml winston prom-client

const express = require('express');
const { parseDicom } = require('dicom-parser');
const sharp = require('sharp');
const ffmpeg = require('fluent-ffmpeg');
const ffmpegPath = require('@ffmpeg-installer/ffmpeg').path;
const pako = require('pako');
const multer = require('multer');
const yaml = require('js-yaml');
const fs = require('fs').promises;
const path = require('path');
const { pipeline } = require('stream/promises');
const winston = require('winston');
const promClient = require('prom-client');

ffmpeg.setFfmpegPath(ffmpegPath);

const config = yaml.load(await fs.readFile('./gateway-config.yaml', 'utf8'));

const logger = winston.createLogger({
  level: config.logLevel || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.Console(),
    new winston.transports.File({ filename: 'gateway.log' })
  ]
});

const register = new promClient.Registry();
promClient.collectDefaultMetrics({ register });
const transcodingDuration = new promClient.Histogram({
  name: 'dicom_transcoding_duration_seconds',
  help: 'Duração do transcoding DICOM para legado',
  labelNames: ['status', 'transfer_s

