// html-json-to-pdf.js
// Dependencies: npm install puppeteer handlebars
// Usage: node html-json-to-pdf.js --input=input.html --output=output.pdf
//        node html-json-to-pdf.js --json=data.json --template=template.hbs --output=report.pdf

import puppeteer from 'puppeteer';
import Handlebars from 'handlebars';
import fs from 'fs/promises';
import path from 'path';
import { fileURLToPath } from 'url';
import { dirname } from 'path';
import yargs from 'yargs';
import { hideBin } from 'yargs/helpers';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// ==========================================
// CONFIGURATION & HELPERS
// ==========================================

const DEFAULT_OPTIONS = {
  format: 'A4',
  margin: { top: '20mm', right: '15mm', bottom: '20mm', left: '15mm' },
  printBackground: true,
  preferCSSPageSize: true,
  scale: 0.95,
  displayHeaderFooter: true,
  headerTemplate: `<div style="font-size: 8px; width: 100%; text-align: center; color: #666; padding-top: 4px;">
                     <span class="title"></span>
                   </div>`,
  footerTemplate: `<div style="font-size: 8px; width: 100%; text-align: center; color: #666; padding-bottom: 4px;">
                     Page <span class="pageNumber"></span> of <span class="totalPages"></span>
                   </div>`,
};

// Injects advanced CSS for print optimization (tables, page breaks, grids)
const PRINT_CSS = `
  <style>
    @page { size: auto; margin: 0; }
    body { margin: 0; padding: 0; -webkit-print-color-adjust: exact; print-color-adjust: exact; }

    /* Table Pagination Control */
    table { width: 100%; border-collapse: collapse; page-break-inside: auto; }
    tr { page-break-inside: avoid; page-break-after: auto; }
    thead

