import { hideBin } from 'yargs/helpers';
import fs from 'fs-extra';
import path from 'path';
import { fileURLToPath } from 'url';

// Configure pdfmake fonts
pdfMake.vfs = pdfFonts.pdfMake.vfs;

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const argv = yargs(hideBin(process.argv))
  .option('input', { alias: 'i', type: 'string', demandOption: true, describe: 'Input file path (HTML or JSON)' })
  .option('output', { alias: 'o', type: 'string', demandOption: true, describe: 'Output PDF file path' })
  .option('type', { alias: 't', type: 'string', choices: ['html', 'json'], demandOption: true, describe: 'Input type' })
  .option('format', { alias: 'f', type: 'string', default: 'A4', describe: 'Paper format (A4, Letter, Legal, etc.)' })
  .option('orientation', { alias: 'r', type: 'string', choices: ['portrait', 'landscape'], default: 'portrait', describe: 'Page orientation' })
  .option('margin', { alias: 'm', type: 'string', default: '2cm', describe: 'Page margin (CSS format, e.g., 1in, 2cm)' })
  .help()
  .alias('help', 'h')
  .parseSync();

