    const printStyles = `
      <style>
        @page { size: ${options.format} ${options.orientation}; margin: ${options.margin}; }
        body { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
        .page-break { page-break-after: always; }
        .avoid-break { page-break-inside: avoid; }
